/* Stage 1: menu preferences, startup defaults and guarded keyboard shortcuts. */
const SettingsUI=(()=>{
 const E=id=>document.getElementById(id),tabs=['menu','sheet','ocr','translation','models','shortcuts'];let draft,recording=null,toastTimer,returnFromTranslation=false,resize=null;
 function toast(message){E('appToast').textContent=message;E('appToast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>E('appToast').hidden=true,3500)}
 function releasePeek(){}
 function selectTab(tab,focus=false){document.querySelector('.settings-footer').hidden=tab==='models';if(tab==='models')ModelManager.refresh();E('settingsSave').textContent=tab==='ocr'?'기본값으로 저장':'저장';E('settingsFooterNote').textContent=tab==='ocr'?'설정은 이 브라우저에 저장됩니다.':'메뉴·학습 시트·단축키 변경 후 저장하세요.';for(const name of tabs){const on=name===tab,b=E('settingsTab-'+name);b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;E('settingsPanel-'+name).hidden=!on}if(focus)E('settingsTab-'+tab).focus();recording=null;renderKeys()}
 function renderKeys(){if(!draft)return;const rows=E('shortcutRows');rows.textContent='';const names={toggle:'형광펜 숨기기 / 보기',quick:'빠른 번역',highlight:'빠른 형광펜',selection:'텍스트 선택'};for(const action of Object.keys(names)){const row=document.createElement('div');row.className='shortcut-row';const label=document.createElement('span');label.textContent=names[action];const button=document.createElement('button');button.type='button';button.id='shortcut-'+action;button.textContent=recording===action?'키를 누르세요…':AppSettings.label(draft.shortcuts[action]);button.setAttribute('aria-label',names[action]+' 단축키 '+button.textContent);button.onclick=()=>{recording=action;renderKeys();E('shortcut-'+action).focus();E('settingsStatus').textContent='사용할 키를 누르세요. Esc로 취소합니다.'};const clear=document.createElement('button');clear.textContent='해제';clear.type='button';clear.setAttribute('aria-label',names[action]+' 단축키 해제');clear.onclick=()=>{draft.shortcuts[action]=null;recording=null;renderKeys()};row.append(label,button,clear);rows.append(row)}}
 function translationSummary(){const t=AppSettings.read().translation;if(!t){E('translationDefaultSummary').textContent='저장된 번역 기본값 없음 · 기존 선택과 브라우저 지원 여부를 사용합니다.';return}const names={auto:'지원 환경 자동 선택',browser:'브라우저 내장',m2m:'M2M100',nllb:'NLLB · 실험용·비상업',horizontal:'일본어 · 가로',vertical:'일본어 · 세로',english:'영어',korean:'한국어'};E('translationDefaultSummary').textContent='저장된 번역 기본값: 도착 언어 '+StudyLanguages.names[t.target]+' · '+names[t.engine]}
 function fill(){draft=AppSettings.read();for(const [id,k]of [['defaultMenuSheet','sheet'],['defaultMenuTranslation','translation'],['defaultMenuSelection','selection']])E(id).checked=draft.menus[k];E('defaultMenuWidth').value=draft.width;E('defaultMenuHeight').value=draft.height;for(const c of ['red','green','blue'])E('defaultSheet-'+c).checked=draft.sheet.colors.includes(c);E('defaultReveal').checked=draft.sheet.reveal;E('applySheetNow').checked=false;for(const c of ['red','green','blue'])E('defaultSensitivity-'+c).value=draft.sheet.sensitivity[c];updateOutputs();translationSummary();renderKeys();E('settingsStatus').textContent=''}
 function open(tab='menu'){if(E('settingsDialog').open){selectTab(tab);return;}releasePeek();globalThis.ReaderSelection?.cancelPending();BetaTranslation.cancelSelection();fill();selectTab(typeof tab==='string'?tab:'menu');E('settingsDialog').showModal()}
 function updateOutputs(){for(const k of ['Width','Height'])E('defaultMenu'+k+'Value').textContent=E('defaultMenu'+k).value+'%';for(const c of ['red','green','blue'])E('sensitivityValue-'+c).textContent=E('defaultSensitivity-'+c).value}
 function orientation(){return matchMedia('(max-width:600px)').matches?'horizontal':'vertical'}
 function layout(width,height){globalThis.ReaderSelection?.invalidate('메뉴 크기가 변경되어 선택을 해제했습니다.');releasePeek();BetaTranslation.cancelSelection();const outer=E('viewport'),books=[epub,epubSecond].filter(Boolean);const ratio=e=>e.scrollTop/Math.max(1,e.scrollHeight-e.clientHeight),saved=ratio(outer),inner=books.map(b=>ratio(b.frame.contentDocument.scrollingElement));document.documentElement.style.setProperty('--menu-width',width+'%');document.documentElement.style.setProperty('--menu-height',height+'%');size();requestAnimationFrame(()=>{outer.scrollTop=saved*Math.max(0,outer.scrollHeight-outer.clientHeight);books.forEach((b,i)=>{const e=b.frame.contentDocument?.scrollingElement;if(e)e.scrollTop=inner[i]*Math.max(0,e.scrollHeight-e.clientHeight)})});const horizontal=orientation()==='horizontal',value=horizontal?height:width;E('menuResize').setAttribute('aria-orientation',orientation());E('menuResize').setAttribute('aria-valuemax',horizontal?'55':'45');E('menuResize').setAttribute('aria-valuenow',String(Math.round(value)));E('menuResize').setAttribute('aria-valuetext','메뉴 '+Math.round(value)+'%')}
 function applyMenus(settings){E('studySheet').open=settings.menus.sheet;E('quickTranslation').open=settings.menus.translation;E('textSelectionMenu').open=settings.menus.selection;layout(settings.width,settings.height)}
 function saveRecognition(){try{RecognitionSettings.save();E('recognitionDefaultSummary').textContent='저장된 기본값: '+RecognitionSettings.names[RecognitionSettings.read().writing]+' · '+(RecognitionSettings.read().ocr==='best'?'정밀':'경량');E('settingsStatus').textContent='OCR 기본값을 저장했습니다. 다음 실행부터 사용합니다.';toast('OCR 기본값을 저장했습니다.')}catch{toast('OCR 기본값을 저장하지 못했습니다.')}}
 function save(){if(E('settingsTab-ocr').getAttribute('aria-selected')==='true'){saveRecognition();return}try{const settings=AppSettings.read();settings.menus={sheet:E('defaultMenuSheet').checked,translation:E('defaultMenuTranslation').checked,selection:E('defaultMenuSelection').checked};settings.width=+E('defaultMenuWidth').value;settings.height=+E('defaultMenuHeight').value;const selectedColors=['red','green','blue'].filter(c=>E('defaultSheet-'+c).checked);settings.sheet={color:selectedColors[0]||'red',colors:selectedColors,mode:sheetMode,reveal:E('defaultReveal').checked,sensitivity:Object.fromEntries(['red','green','blue'].map(c=>[c,+E('defaultSensitivity-'+c).value]))};settings.shortcuts=draft.shortcuts;AppSettings.write(settings);releasePeek();applyMenus(settings);sessionSensitivities={...settings.sheet.sensitivity};if(E('applySheetNow').checked)applySheetDefaults();else paint();E('settingsStatus').textContent='저장했습니다. 메뉴와 감도는 지금 적용하고, 색상·시트 상태 기본값은 다음 책·앱 실행부터 적용합니다.';if(E('applySheetNow').checked)E('settingsStatus').textContent='저장했고 현재 책에도 학습 시트 기본값을 적용했습니다.';toast('설정을 저장했습니다.')}catch{E('settingsStatus').textContent='설정을 저장하지 못했습니다. 브라우저 저장 공간·개인정보 설정을 확인하세요.'}}
 function saveTranslation(){try{const settings=AppSettings.read();settings.translation=BetaTranslation.getSettings();settings.ocr=RecognitionSettings.read();AppSettings.write(settings);translationSummary();toast('번역 기본값을 저장했습니다. 다음 실행부터 적용합니다.');return true}catch{toast('번역 기본값을 저장하지 못했습니다.');return false}}
 function saveResize(width,height){try{const s=AppSettings.read();s.width=width;s.height=height;AppSettings.write(s)}catch{toast('메뉴 크기를 저장하지 못했습니다.')}}
 function capture(e){if(e.repeat)return;e.preventDefault();e.stopImmediatePropagation();if(['Escape','Tab'].includes(e.code)){recording=null;renderKeys();E('settingsStatus').textContent='단축키 지정을 취소했습니다.';return}if(['ControlLeft','ControlRight','ShiftLeft','ShiftRight','AltLeft','AltRight','MetaLeft','MetaRight'].includes(e.code))return;const key=AppSettings.eventKey(e),error=AppSettings.validateKey(key);if(error){E('settingsStatus').textContent=error;return}if(Object.entries(draft.shortcuts).some(([a,k])=>a!==recording&&k&&AppSettings.keyId(k)===AppSettings.keyId(key))){E('settingsStatus').textContent='다른 기능에 지정한 단축키입니다. 다른 키를 선택하세요.';return}const action=recording;draft.shortcuts[action]=key;recording=null;renderKeys();E('shortcut-'+action).focus();E('settingsStatus').textContent='단축키를 지정했습니다. 저장을 눌러 적용하세요.'}
 function keydown(e){if(recording&&E('settingsDialog').open){if(e.isComposing)return;capture(e);return}if(e.defaultPrevented||e.isComposing||e.keyCode===229||e.repeat)return;if(document.querySelector('dialog[open]')||e.target.closest?.('input,textarea,select,[contenteditable]')||(e.code==='Space'&&e.target.closest?.('button,summary')))return;const shortcuts=AppSettings.read().shortcuts,action=['toggle','quick','highlight','selection'].find(a=>AppSettings.matches(e,shortcuts[a]));if(!action||BetaTranslation.isActive()&&!(action==='selection'&&BetaTranslation.isSelecting()))return;e.preventDefault();e.stopImmediatePropagation();if(action==='toggle')E('toggle').click();else if(action==='highlight'){E('highlightMenu').open=true;if(!E('quickHighlight').disabled)E('quickHighlight').click()}else if(action==='selection'){E('textSelectionMenu').open=true;if(!E('recognizeText').disabled)E('recognizeText').click()}else if(!globalThis.Highlights?.isActive()&&!globalThis.ReaderSelection?.isSelect()&&!E('quickTranslate').disabled){E('quickTranslation').open=true;E('quickTranslate').click()}}
 function keyup(){}
 function init(){E('openSettings').onclick=()=>open();E('settingsClose').onclick=()=>E('settingsDialog').close();E('settingsDialog').addEventListener('close',()=>{recording=null;releasePeek()});E('settingsSave').onclick=save;for(const tab of tabs)E('settingsTab-'+tab).onclick=()=>selectTab(tab);document.querySelector('.settings-tabs').onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const index=tabs.findIndex(t=>E('settingsTab-'+t).getAttribute('aria-selected')==='true');selectTab(tabs[e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length],true)};
  for(const id of ['defaultMenuWidth','defaultMenuHeight',...['red','green','blue'].map(c=>'defaultSensitivity-'+c)])E(id).oninput=updateOutputs;
  E('settingsTranslationDetails').onclick=()=>{returnFromTranslation=true;E('settingsDialog').close();E('openTranslation').click()};E('betaDialog').addEventListener('close',()=>{if(returnFromTranslation&&!BetaTranslation.isSelecting()){returnFromTranslation=false;if(!BetaTranslation.isActive()&&!E('settingsDialog').open){E('settingsDialog').showModal();selectTab('translation');translationSummary()}}});E('saveTranslationDefaults').onclick=saveTranslation;
  const saveButton=document.createElement('button');saveButton.id='betaSaveDefaults';saveButton.textContent='현재 설정을 기본값으로 저장';E('openStorage').after(saveButton);saveButton.onclick=saveTranslation;
  const handle=E('menuResize');handle.onpointerdown=e=>{if(e.button!==0||!e.isPrimary)return;e.preventDefault();releasePeek();BetaTranslation.cancelSelection();const s=AppSettings.read();resize={width:s.width,height:s.height};handle.setPointerCapture(e.pointerId);document.body.classList.add('resizing-menu')};handle.onpointermove=e=>{if(!resize)return;const bounds=document.querySelector('main').getBoundingClientRect();if(orientation()==='horizontal')resize.height=Math.round(Math.max(15,Math.min(55,(e.clientY-bounds.top)/bounds.height*100)));else resize.width=Math.round(Math.max(15,Math.min(45,(e.clientX-bounds.left)/bounds.width*100)));layout(resize.width,resize.height)};const end=()=>{if(!resize)return;saveResize(resize.width,resize.height);resize=null;document.body.classList.remove('resizing-menu')};handle.onpointerup=end;handle.onpointercancel=end;handle.onlostpointercapture=end;handle.ondblclick=()=>{const s=AppSettings.read();if(orientation()==='horizontal')s.height=20;else s.width=20;layout(s.width,s.height);saveResize(s.width,s.height)};handle.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home'].includes(e.key))return;e.preventDefault();const s=AppSettings.read(),horizontal=orientation()==='horizontal',key=horizontal?'height':'width',delta=['ArrowLeft','ArrowUp'].includes(e.key)?-2:2;s[key]=e.key==='Home'?20:Math.max(15,Math.min(horizontal?55:45,s[key]+delta));layout(s.width,s.height);saveResize(s.width,s.height)};
  document.addEventListener('keydown',keydown,true);document.addEventListener('keyup',keyup,true);window.addEventListener('blur',()=>{releasePeek();end()});document.addEventListener('visibilitychange',()=>{if(document.hidden)releasePeek()});window.addEventListener('resize',()=>{const s=AppSettings.read();layout(s.width,s.height)});applyMenus(AppSettings.read());
 }
 return {init,open,toast,handleReaderKey:keydown,handleReaderKeyUp:keyup,releasePeek};
})();
SettingsUI.init();
